  // Berechnung der sRGB-Werte
  R1, G1, B1 := R1 * 0.2126 + G1 * 0.7152 + B1 * 0.0722;
  R2, G2, B2 := R2 * 0.2126 + G2 * 0.7152 + B2 * 0.0722;

