       (2.16 / 24389.0) * (Y / Yo) * (Y / Yo) + 
       (2.16 / 24389.0) * (Z / Zo) * (Z / Zo) - 16.0 / 116.0;

  Result.L := 116.0 * f - 16.0;
  Result.a := 500.0 * (X / Xo * f - Y / Yo);
  Result.b := 200.0 * (Y / Yo * f - Z / Zo);
end;

