  Zn = 108.883;
  PiOver180 = Pi / 180.0;
  Epsilon = 0.008856; // 6^3 / 29^3
  Kappa   = 903.3;    // 29^3 / 3^3

// -----------------------------------------------------------------------------
// sRGB (0..1) to linear RGB
function SRGBToLinear(v: Double): Double;
begin
  if v <= 0.04045 then
    Result := v / 12.92
  else
    Result := Power((v + 0.055) / 1.055, 2.4);
end;

// -----------------------------------------------------------------------------
// RGB (0..255) to CIELAB
function RGBToLab(R, G, B: Byte): TLab;
var
  r, g, b: Double;
  X, Y, Z: Double;
  fx, fy, fz: Double;
begin
  // Normalize to [0,1]
  r := R / 255.0;
  g := G / 255.0;
  b := B / 255.0;

  // Linearize
  r := SRGBToLinear(r);
  g := SRGBToLinear(g);
  b := SRGBToLinear(b);

  // sRGB to XYZ (D65)
  X :=  0.4124564 * r + 0.3575761 * g + 0.1804375 * b;
  Y :=  0.2126729 * r + 0.7151522 * g + 0.0721750 * b;
  Z :=  0.0193339 * r + 0.1191920 * g + 0.9503041 * b;

  // Scale to reference white
  X := X * 100.0 / Xn;
  Y := Y * 100.0 / Yn;
  Z := Z * 100.0 / Zn;

  // f(t) function
  if X > Epsilon then fx := Power(X, 1/3) else fx := (Kappa * X + 16) / 116;
  if Y > Epsilon then fy := Power(Y, 1/3) else fy := (Kappa * Y + 16) / 116;
  if Z > Epsilon then fz := Power(Z, 1/3) else fz := (Kappa * Z + 16) / 116;

  Result.L := 116 * fy - 16;
  Result.a := 500 * (fx - fy);
  Result.b := 200 * (fy - fz);
end;

