  deltaLp, deltaCp, deltaHp, SL, SC, SH, RT, deltaE: Double;
  hpDiff, hpSum, hpDiffDeg, hpSumDeg, T, deltaTheta, RC, RTfactor: Double;
begin
  L1 := Lab1.L; a1 := Lab1.a; b1 := Lab1.b;
  L2 := Lab2.L; a2 := Lab2.a; b2 := Lab2.b;

