  C1 := Sqrt(a1*a1 + b1*b1);
  C2 := Sqrt(a2*a2 + b2*b2);
  C_bar := (C1 + C2) / 2.0;

  G := 0.5 * (1 - Sqrt(Power(C_bar, 7) / (Power(C_bar, 7) + Power(25.0, 7))));

  a1p := a1 * (1 + G);
  a2p := a2 * (1 + G);

  C1p := Sqrt(a1p*a1p + b1*b1);
