  L1 := Lab1.L; a1 := Lab1.a; b1 := Lab1.b;
  L2 := Lab2.L; a2 := Lab2.a; b2 := Lab2.b;

  // Step 1: L' and C'
  C1 := Sqrt(a1*a1 + b1*b1);
  C2 := Sqrt(a2*a2 + b2*b2);
  C_bar := (C1 + C2) / 2.0;

  G := 0.5 * (1 - Sqrt(Power(C_bar, 7) / (Power(C_bar, 7) + Power(25.0, 7))));

  a1p := a1 * (1 + G);
  a2p := a2 * (1 + G);

  C1p := Sqrt(a1p*a1p + b1*b1);
  C2p := Sqrt(a2p*a2p + b2*b2);

