  if (b1 = 0) and (a1p = 0) then h1p := 0.0
  else h1p := ArcTan2(b1, a1p);
  if (b2 = 0) and (a2p = 0) then h2p := 0.0
  else h2p := ArcTan2(b2, a2p);

  if h1p < 0 then h1p := h1p + 2*Pi;
  if h2p < 0 then h2p := h2p + 2*Pi;

  // Step 3: ΔL', ΔC', ΔH'
  deltaLp := L2 - L1;
  deltaCp := C2p - C1p;

  // ΔH'
  if (C1p * C2p) = 0 then
    deltaHp := 0.0
  else
  begin
    hpDiff := h2p - h1p;
    if Abs(hpDiff) <= Pi then
      deltaHp := hpDiff
    else if hpDiff > Pi then
      deltaHp := hpDiff - 2*Pi
    else
      deltaHp := hpDiff + 2*Pi;
    deltaHp := 2 * Sqrt(C1p*C2p) * Sin(deltaHp / 2.0);
  end;

