  deltaTheta := 30 * Exp(-Power((hpSumDeg - 275) / 25, 2));
  RC := 2 * Sqrt(Power(C_bar, 7) / (Power(C_bar, 7) + Power(25.0, 7)));
  RT := -RC * Sin(2 * deltaTheta * PiOver180);

  // Step 6: Final ΔE
  deltaE := Sqrt(
    Power(deltaLp / SL, 2) +
    Power(deltaCp / SC, 2) +
    Power(deltaHp / SH, 2) +
    RT * (deltaCp / SC) * (deltaHp / SH)
  );

  Result := deltaE;
end;

