  // Für eine exakte Implementierung müsste die vollständige sRGB-Funktion implementiert werden.

function sRGBToLinear(C: Byte): Double;
var
  C_float: Double;
begin
  C_float := C / 255.0;
  if C_float <= 0.04045 then
    Result := C_float / 12.92;
  else
    Result := ((C_float + 0.055) / 1.055) ^ 2.4;
end;

