  fX := X / Xn_val;
  fY := Y / Yn_val;
  fZ := Z / Zn_val;

  // CIELAB Berechnung
  f := sqrt(fY * fY + fX * fX + fZ * fZ);

  if f == 0.0 then
    L := 0.0
  else
  begin
    L := 116.0 * f - 16.0;
    a := 500.0 * (fY - L);
    b := 200.0 * (L - 16.0);
  end;

  Result.L := L;
  Result.a := a;
  Result.b := b;
end;

