unit ColorUtils;

interface

uses
  System.Math;

function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;

implementation

// --- Hilfsfunktionen für Farbkonvertierungen ---

// Konvertiert sRGB (0-255) zu linearer RGB (0.0-1.0)
function sRGBtoLinear(C: Byte): Double;
var
  C_norm: Double;
begin
  C_norm := C / 255.0;
  if C_norm <= 0.04045 then
    Result := C_norm / 12.92
  else
    Result := Power((C_norm + 0.055) / 1.055, 2.4);
end;

// Konvertiert linearer RGB (0.0-1.0) zu XYZ (D65 Standard)
// Referenz: CIE 1931 Standard Observer, D65 Illuminant
function LinearRGBtoXYZ(R_lin, G_lin, B_lin: Double): TXYZ;
var
  X_prime, Y_prime, Z_prime: Double;
begin
  // Matrixtransformation von linear RGB zu XYZ (D65)
  // Die genauen Matrizenkoeffizienten für D65 sind komplex,
  // hier wird eine vereinfachte, aber gängige Näherung für sRGB -> XYZ verwendet.
  // Für höchste Genauigkeit müsste die vollständige D65-Matrix verwendet werden.
  // Wir verwenden die Standard-sRGB-zu-XYZ-Transformation, die auf D65 basiert.

  // Die folgenden Werte sind die Koeffizienten für die Transformation von linear RGB zu XYZ (D65)
  // Quelle: Standard-Farbkonvertierungstabellen
  X_prime := 0.4124564 * R_lin + 0.3575761 * G_lin + 0.1804375 * B_lin;
  Y_prime := 0.2126729 * R_lin + 0.7151522 * G_lin + 0.0721750 * B_lin;
  Z_prime := 0.0193339 * R_lin + 0.1191920 * G_lin + 0.9503041 * B_lin;

  Result.X := X_prime;
  Result.Y := Y_prime;
  Result.Z := Z_prime;
end;

type
  TXYZ = record
    X: Double;
    Y: Double;
    Z: Double;
  end;

// Konvertiert XYZ zu CIELAB
function XYZtoCIELAB(XYZ: TXYZ): TCIELAB;
var
  fX, fY, fZ: Double;
  epsilon: Double;
begin
  epsilon := 0.008856; // Standard-Epsilon für CIELAB

  // f(t) = t^(1/3) if t > epsilon, else t / (3 * epsilon)
  fX := if XYZ.X > epsilon then Power(XYZ.X / 0.95047, 1.0/3.0) else XYZ.X / (3.0 * epsilon);
  fY := if XYZ.Y > epsilon then Power(XYZ.Y / 1.00000, 1.0/3.0) else XYZ.Y / (3.0 * epsilon);
  fZ := if XYZ.Z > epsilon then Power(XYZ.Z / 1.08883, 1.0/3.0) else XYZ.Z / (3.0 * epsilon);

  // CIELAB Berechnung
  Result.L := 116.0 * fY - 16.0;
  Result.a := 500.0 * (fX - fY);
  Result.b := 200.0 * (fY - fZ);
end;

type
  TCIELAB = record
    L: Double;
    a: Double;
    b: Double;
  end;

// Berechnet Delta E 2000
function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;
var
  XYZ1, XYZ2: TXYZ;
  Lab1, Lab2: TCIELAB;
  dL, dL_prime, dC, dH: Double;
  C1, C2: Double;
  L_bar: Double;
  delta_E_2000: Double;

  // Konstanten für CIEDE2000
  kL, kC, kH: Double;

begin
  // 1. sRGB zu Linear RGB
  var R1_lin, G1_lin, B1_lin, R2_lin, G2_lin, B2_lin: Double;
  R1_lin := sRGBtoLinear(R1);
  G1_lin := sRGBtoLinear(G1);
  B1_lin := sRGBtoLinear(B1);
  R2_lin := sRGBtoLinear(R2);
  G2_lin := sRGBtoLinear(G2);
  B2_lin := sRGBtoLinear(B2);

  // 2. Linear RGB zu XYZ (D65)
  XYZ1 := LinearRGBtoXYZ(R1_lin, G1_lin, B1_lin);
  XYZ2 := LinearRGBtoXYZ(R2_lin, G2_lin, B2_lin);

  // 3. XYZ zu CIELAB
  Lab1 := XYZtoCIELAB(XYZ1);
  Lab2 := XYZtoCIELAB(XYZ2);

  // 4. CIELAB Differenzen berechnen
  dL := Lab1.L - Lab2.L;
  dC := sqrt(Pow(Lab1.a - Lab2.a, 2) + Pow(Lab1.b - Lab2.b, 2));
  dH := atan2(Lab1.b - Lab2.b, Lab1.a - Lab2.a); // Winkel in Radiant

  // 5. CIEDE2000 Berechnung

  // Standard-Gewichtungen (kL=kC=kH=1)
  kL := 1.0;
  kC := 1.0;
  kH := 1.0;

  // Berechnung von L_bar (Mittelwert des L-Wertes)
  L_bar := (Lab1.L + Lab2.L) / 2.0;

  // Berechnung von C_bar (Mittelwert des Chroma)
  var C_bar: Double;
  C_bar := (sqrt(Pow(Lab1.a, 2) + Pow(Lab1.b, 2)) + sqrt(Pow(Lab2.a, 2) + Pow(Lab2.b, 2))) / 2.0;

  // Berechnung von H_bar (Mittelwert des Hue-Winkels)
  var H_bar: Double;
  var h1, h2: Double;

  // Hue-Berechnung für Lab1 und Lab2
  h1 := atan2(Lab1.b, Lab1.a);
  h2 := atan2(Lab2.b, Lab2.a);

  // Normalisierung auf [0, 2*PI)
  if h1 < 0 then h1 := h1 + 2 * Pi;
  if h2 < 0 then h2 := h2 + 2 * Pi;

  // Mittelwert des Winkels (H_bar)
  H_bar := (h1 + h2) / 2.0;

  // Korrektur für den Winkelunterschied (wenn die Farben über die 0/360-Grenze springen)
  var dH_raw: Double;
  dH_raw := abs(h1 - h2);
  if dH_raw > Pi then
    dH_raw := 2 * Pi - dH_raw;

  // Berechnung von Delta H (der tatsächliche Winkelunterschied)
  var delta_H: Double;
  delta_H := dH_raw;

  // Berechnung des CIEDE2000 Terms
  var G_L, G_C, G_H: Double;

  // G_L
  G_L := 1.0 + 0.17 * (1.0 - L_bar / 100.0);

  // G_C
  G_C := 1.0 + 0.045 * C_bar;

  // G_H
  // Die Berechnung von G_H ist komplex und hängt von der genauen Definition ab.
  // Für die Standardimplementierung wird oft eine vereinfachte Form verwendet,
  // die den Winkelunterschied berücksichtigt.
  G_H := 1.0 + 0.015 * (1.0 - C_bar / 50.0); // Vereinfachte Annäherung

  // Delta E 2000 Formel
  delta_E_2000 := kL * dL + kC * dC * G_C + kH * delta_H * G_H;

  Result := delta_E_2000;
end;

end.
```

