procedure RGBToXYZ(R, G, B: Byte; out X, Y, Z: Double);
var
  r, g, b: Double;
begin
  r := SRGBToLinear(R / 255.0);
  g := SRGBToLinear(G / 255.0);
  b := SRGBToLinear(B / 255.0);

