  Xn = 95.047;  // D65 reference white
  Yn = 100.000;
  Zn = 108.883;
var
  fx, fy, fz: Double;
begin
  fx := fXYZ(X / Xn);
  fy := fXYZ(Y / Yn);
  fz := fXYZ(Z / Zn);

  L := 116 * fy - 16;
  a := 500 * (fx - fy);
  b := 200 * (fy - fz);
