function LabDeltaE2000(L1, a1, b1, L2, a2, b2: Double): Double;
var
  C1, C2, Cbar, G, a1p, a2p, C1p, C2p, Cbarp, h1p, h2p, hbarp, T,
  deltaLp, deltaCp, deltaHp, SL, SC, SH, RT, deltaTheta, RC, deltaHprime: Double;
  h1pDeg, h2pDeg, hbarpDeg: Double;
begin
  // 1. Compute C1, C2
  C1 := Sqrt(a1 * a1 + b1 * b1);
  C2 := Sqrt(a2 * a2 + b2 * b2);

  // 2. Compute G
  Cbar := (C1 + C2) / 2;
  G := 0.5 * (1 - Sqrt(Power(Cbar, 7) / (Power(Cbar, 7) + Power(25, 7))));

  // 3. Compute a' values
  a1p := (1 + G) * a1;
  a2p := (1 + G) * a2;

  // 4. Compute C' values
  C1p := Sqrt(a1p * a1p + b1 * b1);
  C2p := Sqrt(a2p * a2p + b2 * b2);
  Cbarp := (C1p + C2p) / 2;

  // 5. Compute h' values
  h1p := Atan2(b1, a1p);
  if h1p < 0 then h1p := h1p + 2 * Pi;
  h2p := Atan2(b2, a2p);
  if h2p < 0 then h2p := h2p + 2 * Pi;

  // 6. Compute hbar'
  if Abs(h1p - h2p) > Pi then
    hbarp := (h1p + h2p + 2 * Pi) / 2
  else
    hbarp := (h1p + h2p) / 2;

  // 7. Compute T
  T := 1
       - 0.17 * Cos(hbarp - Pi / 6)
       + 0.24 * Cos(2 * hbarp)
       + 0.32 * Cos(3 * hbarp + Pi / 30)
       - 0.20 * Cos(4 * hbarp - 63 * Pi / 180);

  // 8. Compute delta L', delta C', delta H'
  deltaLp := L2 - L1;
  deltaCp := C2p - C1p;

  if (C1p * C2p) = 0 then
    deltaHp := 0
