      if h2p <= h1p then
        deltaHp := 2 * Sqrt(C1p * C2p) * Sin((deltaHprime + 2 * Pi) / 2)
      else
        deltaHp := 2 * Sqrt(C1p * C2p) * Sin((deltaHprime - 2 * Pi) / 2);
    end;
  end;

