  SL := 1 + (0.015 * Power(Lbarp - 50, 2)) / Sqrt(20 + Power(Lbarp - 50, 2));
  SC := 1 + 0.045 * Cbarp;
  SH := 1 + 0.015 * Cbarp * Sqrt(T);

  // 10. Compute RT
  hbarpDeg := hbarp * 180 / Pi;
  deltaTheta := 30 * Pi / 180 * Exp(-Power((hbarpDeg - 275) / 25, 2));
  RC := 2 * Sqrt(Power(Cbarp, 7) / (Power(Cbarp, 7) + Power(25, 7)));
  RT := -RC * Sin(2 * deltaTheta);

  // 11. Final Delta E
  Result := Sqrt(
    Power(deltaLp / SL, 2) +
    Power(deltaCp / SC, 2) +
    Power(deltaHp / SH, 2) +
    RT * (deltaCp / SC) * (deltaHp / SH)
  );
