  // 1. Compute C1, C2
  C1 := Sqrt(a1 * a1 + b1 * b1);
  C2 := Sqrt(a2 * a2 + b2 * b2);

  // 2. Compute G
  Cbar := (C1 + C2) / 2;
  G := 0.5 * (1 - Sqrt(Power(Cbar, 7) / (Power(Cbar, 7) + Power(25, 7))));

  // 3. Compute a' values
  a1p := (1 + G) * a1;
  a2p := (1 + G) * a2;

  // 4. Compute C' values
  C1p := Sqrt(a1p * a1p + b1 * b1);
  C2p := Sqrt(a2p * a2p + b2 * b2);
  Cbarp := (C1p + C2p) / 2;

