function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;
var
  L1, a1, b1, L2, a2, b2: Double;
  deltaL, deltaC, deltaH: Double;
  deltaE: Double;
  function RGBToCIELAB(R, G, B: Byte): TXYZ;
  var
    R_linear, G_linear, B_linear: Double;
    X, Y, Z: Double;
    Xn, Yn, Zn: Double;
    fx, fy, fz: Double;
    L, a, b: Double;
  begin
    // Convert RGB to linear RGB
    R_linear := R / 255;
    if R_linear <= 0.04045 then
      R_linear := R_linear / 12.92
    else
      R_linear := Power((R_linear + 0.055)/1.055, 2.4);
    G_linear := G / 255;
    if G_linear <= 0.04045 then
      G_linear := G_linear / 12.92
    else
      G_linear := Power((G_linear + 0.055)/1.055, 2.4);
    B_linear := B / 255;
    if B_linear <= 0.04045 then
      B_linear := B_linear / 12.92
    else
      B_linear := Power((B_linear + 0.055)/1.055, 2.4);

    // Convert linear RGB to XYZ
    X := 0.4124569 * R_linear + 0.3575761 * G_linear + 0.0804025 * B_linear;
    Y := 0.2126729 * R_linear + 0.7151522 * G_linear + 0.0721693 * B_linear;
    Z := 0.0193339 * R_linear + 0.1191990 * G_linear + 0.9503998 * B_linear;

    // Reference white D65
    Xn := 0.95047;
    Yn := 1.0;
    Zn := 1.08883;

    // Compute fx, fy, fz
    fx := X / Xn;
    fy := Y / Yn;
    fz := Z / Zn;

    // Compute F(t)
    function F(t: Double): Double;
    begin
      if t > (6/29)^3 then
        Result := Power(t, 1/3)
      else
        Result := (7.787 * t) + 16/116;
    end;

    L := 116 * F(fy) - 16;
    a := 500 * (F(fx) - F(fy);
    b := 200 * (F(fy) - F(fz);

    Result.X := X;
    Result.Y := Y;
    Result.Z := Z;
  end;

  // Convert both RGB to CIELAB
  var
    X1, Y1, Z1: Double;
    X2, Y2, Z2: Double;
  begin
    X1 := 0.4124569 * (R1/255) + 0.3575761 * (G1/255) + 0.0804025 * (B1/255);
    Y1 := 0.2126729 * (R1/255) + 0.7151522 * (G1/255) + 0.0721693 * (B1/255);
    Z1 := 0.0193339 * (R1/255) + 0.1191990 * (G1/255) + 0.9503998 * (B1/255);

    X2 := 0.4124569 * (R2/255) + 0.3575761 * (G2/255) + 0.0804025 * (B2/255);
    Y2 := 0.2126729 * (R2/255) + 0.7151522 * (G2/250) + 0.0721693 * (B2/255);
    Z2 := 0.0193339 * (R2/255) + 0.1191990 * (G2/255) + 0.9503998 * (B2/255);

    // Reference white D65
    Xn := 0.95047;
    Yn := 1.0;
    Zn := 1.08883;

    // Compute F(t) for both colors
    function F(t: Double): Double;
    begin
      if t > (6/29)^3 then
        Result := Power(t, 1/3)
      else
        Result := (7.787 * t) + 16/116;
    end;

    // Compute CIELAB for first color
    fx := X1 / Xn;
    fy := Y1 / Yn;
    fz := Z1 / Zn;
    L1 := 116 * F(fy) - 16;
    a1 := 500 * (F(fx) - F(fy);
    b1 := 200 * (F(fy) - F(fz);

    // Compute CIELAB for second color
    fx := X2 / Xn;
    fy := Y2 / Yn;
    fz := Z2 / Zn;
    L2 := 116 * F(fy) - 16;
    a2 := 500 * (F(fx) - F(fy);
    b2 := 200 * (F(fy) - F(fz);

