  R2L := sRGBtoLinear(R2 / 255.0);
  G2L := sRGBtoLinear(G2 / 255.0);
  B2L := sRGBtoLinear(B2 / 255.0);

  LinearRGBtoXYZ(R1L, G1L, B1L, X1, Y1, Z1);
  LinearRGBtoXYZ(R2L, G2L, B2L, X2, Y2, Z2);

  XYZtoLAB(X1, Y1, Z1, L1, a1, b1);
  XYZtoLAB(X2, Y2, Z2, L2, a2, b2);

  C1 := Sqrt(a1 * a1 + b1 * b1);
  C2 := Sqrt(a2 * a2 + b2 * b2);

  G := 0.5 * (1.0 - Sqrt(Power(C1, 7) / (Power(C1, 7) + Power(C2, 7))));

  a1p := a1 * (1.0 + G);
  a2p := a2 * (1.0 + G);

  C1p := Sqrt(a1p * a1p + b1 * b1);
  C2p := Sqrt(a2p * a2p + b2 * b2);

  h1p := ArcTan2(b1, a1p) * 180.0 / Pi;
  h2p := ArcTan2(b2, a2p) * 180.0 / Pi;
  if h1p < 0 then h1p := h1p + 360.0;
  if h2p < 0 then h2p := h2p + 360.0;

