  lr := sRGBToLinear(R);
  lg := sRGBToLinear(G);
  lb := sRGBToLinear(B);

  X := (0.4124564 * lr + 0.3575761 * lg + 0.1804375 * lb) * 100.0;
  Y := (0.2126729 * lr + 0.7151522 * lg + 0.0721750 * lb) * 100.0;
  Z := (0.0193339 * lr + 0.1191920 * lg + 0.9503041 * lb) * 100.0;

