    bl := bb / 12.92;

  Result.X := Matrix00 * rl + Matrix01 * gl + Matrix02 * bl;
  Result.Y := Matrix10 * rl + Matrix11 * gl + Matrix12 * bl;
  Result.Z := Matrix20 * rl + Matrix21 * gl + Matrix22 * bl;
end;

function XYZToLab(X, Y, Z: Double): TLab;
var
  fx, fy, fz: Double;
begin
  fx := LabF(X / Xn);
  fy := LabF(Y / Yn);
  fz := LabF(Z / Zn);

  Result.L := 116.0 * fy - 16.0;
  Result.A := 500.0 * (fx - fy);
  Result.B := 200.0 * (fy - fz);
end;

function RGBToLab(R, G, B: Byte): TLab;
var
  xyz: TXyz;
begin
  xyz := RGBToXYZ(R, G, B);
  Result := XYZToLab(xyz.X, xyz.Y, xyz.Z);
end;

function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;
var
  Lab1, Lab2: TLab;
  C1, C2, meanC, h1, h2, meanH, T: Double;
  dL, dC, dH, dL_, dC_, dH_: Double;
  meanL: Double;
begin
  Lab1 := RGBToLab(R1, G1, B1);
  Lab2 := RGBToLab(R2, G2, B2);

  C1 := Sqrt(Sqr(Lab1.A) + Sqr(Lab1.B));
  C2 := Sqrt(Sqr(Lab2.A) + Sqr(Lab2.B));
  meanC := (C1 + C2) / 2.0;

  h1 := 0.0;
  h2 := 0.0;
  if C1 > 1.0E-10 then
    h1 := ArcTan2(Lab1.B, Lab1.A) * 180.0 / Pi;
  if C2 > 1.0E-10 then
    h2 := ArcTan2(Lab2.B, Lab2.A) * 180.0 / Pi;

  meanH := 0.0;
  if meanC > 1.0E-10 then
    meanH := (C1 * Cos(h1 * Pi / 180.0) + C2 * Cos(h2 * Pi / 180.0)) / meanC;

  T := 1.0 - 0.17 * Cos((meanH - h1 + 30.0) * Pi / 180.0)
       + 0.24 * Cos(2.0 * (meanH - h1) * Pi / 180.0)
       - 0.32 * Cos(2.0 * (meanH + h1) * Pi / 180.0)
       - 0.20 * Cos(2.0 * (meanH - h1 - 60.0) * Pi / 180.0);

  dL := Lab2.L - Lab1.L;
  dC := C2 - C1;
  dH := h2 - h1;
  if dH > 180.0 then
    dH := dH - 360.0;
  if dH < -180.0 then
    dH := dH + 360.0;

  meanL := (Lab1.L + Lab2.L) / 2.0;

  dL_ := dL;
  dC_ := dC * (1.0 + 0.045 * (1.0 - Cos(2.0 * meanC * Pi / 180.0)) * (1.0 - T));
  dH_ := dH * (1.0 + 0.045 * (1.0 - Cos(2.0 * meanH * Pi / 180.0)) * (1.0 - T));

  Result := Sqrt(Sqr(dL_) + Sqr(dC_) + Sqr(dH_) * (1.0 - Cos(2.0 * meanH * Pi / 180.0) * Sqr(dC_ / ((C1 + C2) / 2.0))));
end;

end.
